import currency as tau
import con_collider_contract as lhc
import con_rocketswap_official_v1_1 as rswp
random.seed()
__owner = Variable(contract='con_collider_006', name='owner')
__min_amount = Variable(contract='con_collider_006', name='min_amount')
__max_amount = Variable(contract='con_collider_006', name='max_amount')


def ____():
    __owner.set(ctx.caller)
    __min_amount.set(15)
    __max_amount.set(50)


@__export('con_collider_006')
def collide(amount: float):
    error = 'Min amount is ' + str(__min_amount.get())
    assert amount >= __min_amount.get(), error
    error = 'Max amount is ' + str(__max_amount.get())
    assert amount <= __max_amount.get(), error
    tau.transfer_from(amount=amount, to=ctx.this, main_account=ctx.caller)
    __rswp_prices = ForeignHash(foreign_contract=
        'con_rocketswap_official_v1_1', foreign_name='prices', contract=
        'con_collider_006', name='rswp_prices')
    lhc_price = __rswp_prices['con_collider_contract']
    lhc_amount = amount / lhc_price
    if random.choice([True, False]):
        tau.transfer(amount=amount, to=ctx.caller)
        lhc.transfer(amount=lhc_amount, to=ctx.caller)
        return 'You won ' + str(amount) + ' TAU and ' + str(lhc_amount
            ) + ' LHC'
    else:
        tau.approve(amount=amount, to='con_rocketswap_official_v1_1')
        rswp.buy(contract='con_collider_contract', currency_amount=amount,
            minimum_received=lhc_amount * decimal('0.51'), token_fees=False)
        return 'You lost ' + str(amount) + ' TAU'


@__export('con_collider_006')
def deposit_tau(amount: float):
    tau.transfer_from(amount=amount, to=ctx.this, main_account=ctx.caller)


@__export('con_collider_006')
def withdraw_tau(amount: float):
    error = 'Only the owner can withdraw TAU'
    assert __owner.get() == ctx.caller, error
    tau.transfer(amount=amount, to=ctx.caller)


@__export('con_collider_006')
def deposit_lhc(amount: float):
    lhc.transfer_from(amount=amount, to=ctx.this, main_account=ctx.caller)


@__export('con_collider_006')
def withdraw_lhc(amount: float):
    error = 'Only the owner can withdraw LHC'
    assert __owner.get() == ctx.caller, error
    lhc.transfer(amount=amount, to=ctx.caller)


@__export('con_collider_006')
def set_min(amount: float):
    error = 'Only the owner can adjust MIN value'
    assert __owner.get() == ctx.caller, error
    __min_amount.set(amount)


@__export('con_collider_006')
def set_max(amount: float):
    error = 'Only the owner can adjust MAX value'
    assert __owner.get() == ctx.caller, error
    __max_amount.set(amount)
